import { Command } from 'commander';
import chalk from 'chalk';
import { adapterRegistry } from './adapters/registry.js';
import { registerAllAdapters } from './adapters/index.js';
import { registerAllChecks } from './checks/index.js';
import { initIOCDatabase } from './ioc/database.js';
import { isFeedStale } from './ioc/updater.js';
import { initAdvisoryDatabase } from './advisory/database.js';
import { isAdvisoryFeedStale } from './advisory/updater.js';
import { loadUserPlugins } from './user-plugins/loader.js';
import { loadAndRegisterRules } from './rules/index.js';
import { checkRegistry } from './core/check-registry.js';
import { logError, setDebug } from './core/debug.js';
import { assertZoneGraphsValid } from './core/zone-graph-validator.js';
import { defaultZoneGraph } from './core/default-zone-graph.js';
import { AGENT_TYPES, isScannableAgentType } from './core/types.js';
import { VERSION } from './version.js';
import { isReportFormat, reportFormats } from './reporting/index.js';
import { colorDisabled } from './core/color.js';

if (colorDisabled(process.argv.slice(2), process.env)) chalk.level = 0;

// Derive the list of scannable agent types from the canonical AGENT_TYPES array
// so `--agent <type>` help strings can't drift as new adapters are added.
// 'mcp' and 'skill-audit' are filtered out — they have dedicated commands
// (`vaso mcp scan`, `vaso skill audit`) rather than being passed via --agent.
const SCANNABLE_AGENTS = AGENT_TYPES.filter(t => t !== 'mcp' && t !== 'skill-audit').join(', ');

function validateAgentOption(options: { agent?: string }): boolean {
  if (options.agent && !isScannableAgentType(options.agent)) {
    console.error(chalk.red(`Invalid --agent "${options.agent}". Use one of: ${SCANNABLE_AGENTS}.`));
    process.exitCode = 2;
    return false;
  }
  return true;
}

/**
 * Reject an unknown --format before any work starts (a scan used to run to
 * completion and only then fail to render). Report commands accept every
 * registered reporter, including user-plugin ones (loaded in preAction).
 */
function validateFormatOption(options: { format?: string }, allowed?: readonly string[]): boolean {
  const format = options.format;
  if (format === undefined) return true;
  const valid = allowed ? allowed.includes(format) : isReportFormat(format);
  if (!valid) {
    console.error(chalk.red(`Invalid --format "${format}". Use one of: ${(allowed ?? reportFormats()).join(', ')}.`));
    process.exitCode = 2;
    return false;
  }
  return true;
}

const LISTING_FORMATS = ['terminal', 'json'] as const;

const BANNER = `
${chalk.red('██╗   ██╗ █████╗ ███████╗ ██████╗')}
${chalk.red('██║   ██║██╔══██╗██╔════╝██╔═══██╗')}
${chalk.red('██║   ██║███████║███████╗ ██║   ██║')}
${chalk.red('╚██╗ ██╔╝██╔══██║╚════██║██║   ██║')}
${chalk.red(' ╚████╔╝ ██║  ██║███████║╚██████╔╝')}
${chalk.red('  ╚═══╝  ╚═╝  ╚═╝╚══════╝ ╚═════╝')}
${chalk.dim(`  VULNEX Agent Security Observer v${VERSION}`)}
${chalk.dim('  Agent-agnostic security scanner for AI deployments')}
`;

/** Banner and loader warnings go to stderr so stdout carries only command
 *  output (`vaso scan -f json | jq`, `vaso probe manifest > m.json`). */
function printBanner(): void {
  console.error(BANNER);
}

// Register adapters and checks
registerAllAdapters();
registerAllChecks();
assertZoneGraphsValid(adapterRegistry, checkRegistry, defaultZoneGraph);

const program = new Command();

program
  .name('vaso')
  .description('VULNEX Agent Security Observer — security scanner for AI agent deployments')
  .version(VERSION, '-v, --version')
  // Parse errors (unknown option/command, missing or extra argument) are
  // usage errors — exit 2, not commander's 1, which CI reads as "findings".
  // Set before the subcommands are defined: they inherit it. Help/version exit 0.
  .exitOverride(err => process.exit(err.exitCode === 0 ? 0 : 2))
  .option('--debug', 'print full stack traces on errors')
  .hook('preAction', async (_thisCommand, actionCommand) => {
    setDebug(Boolean(program.opts().debug));

    // Commander's preAction signature: thisCommand = the program (where the hook
    // was registered), actionCommand = the subcommand about to run. Subcommand
    // options like --silent live on actionCommand.opts(), not thisCommand's.
    const subOpts = actionCommand.opts?.() ?? {};
    const silent = Boolean(subOpts.silent);

    if (!silent) printBanner();

    // Load user plugins from ~/.vaso/plugins/
    const userPlugins = await loadUserPlugins();
    if (!silent) {
      for (const p of userPlugins) {
        if (p.status === 'error') {
          console.error(chalk.yellow(`  Warning: user plugin "${p.name}" failed to load: ${p.error}\n`));
        }
      }
    }

    // Load declarative rules only for commands that run checks (scan, fix)
    const commandName = actionCommand.name();
    const needsRules = commandName === 'scan' || commandName === 'fix';

    if (needsRules) {
      const skipRules = subOpts.customRules === false;

      if (!skipRules) {
        const extraPaths = subOpts.rules as string[] | undefined;
        const rulesResult = await loadAndRegisterRules(checkRegistry, { extraPaths });
        // A rule file named on the command line that can't be read is an
        // unreadable input, like a missing --snapshot or --inventory (exit 2)
        const unreadable = rulesResult.loadResult.files.find(f => f.source === 'explicit' && f.unreadable);
        if (unreadable) {
          throw new Error(`--rules ${unreadable.filePath}: ${unreadable.errors[0]?.message ?? 'cannot be read'}`);
        }
        if (!silent) {
          for (const err of rulesResult.loadResult.allErrors) {
            const loc = err.rule ? ` (rule ${err.rule})` : '';
            console.error(chalk.yellow(`  Warning: rule file ${err.file}${loc}: ${err.message}\n`));
          }
          for (const w of rulesResult.loadResult.warnings) {
            console.error(chalk.yellow(`  Warning: rule file ${w.file} (rule ${w.rule}): ${w.message}\n`));
          }
          for (const skip of rulesResult.skipped) {
            console.error(chalk.yellow(`  Warning: rule "${skip.id}" skipped: ${skip.reason}\n`));
          }
          if (rulesResult.registered.length > 0) {
            console.error(chalk.dim(`  Loaded ${rulesResult.registered.length} declarative rule(s)\n`));
          }
        }
      }
    }

    await initIOCDatabase();
    await initAdvisoryDatabase();

    // Warn about stale feeds for non-update commands. Diagnostics go to stderr
    // with the banner: stdout carries reports (`-f json`) and `probe manifest`.
    if (!silent && actionCommand.name() !== 'update') {
      if (isFeedStale()) {
        console.error(
          chalk.yellow('  IOC feed is stale. Run `vaso update` for latest threat data.\n'),
        );
      }
      if (isAdvisoryFeedStale()) {
        console.error(
          chalk.yellow('  Advisory feed is stale. Run `vaso update` for latest advisories.\n'),
        );
      }
    }
  });

// Show banner on help
const originalHelp = program.helpInformation.bind(program);
program.helpInformation = function () {
  printBanner();
  return originalHelp();
};

program
  .command('scan')
  .description('Scan installed AI agents for security issues')
  .option('-a, --agent <type>', `scan a specific agent (${SCANNABLE_AGENTS})`)
  .option('-f, --format <format>', 'output format (terminal, json, sarif, markdown, html, csv, junit)', 'terminal')
  .option('-o, --output <file>', 'write report to file (single combined output)')
  .option('--output-dir <dir>', 'write one file per host as <dir>/<hostname>.<ext> (local scans use the local hostname)')
  .option('--save-baseline', 'save scan results as baseline')
  .option('--diff', 'compare against saved baseline')
  .option('--all-users', 'scan all user accounts (requires root/sudo)')
  .option('--silent', 'suppress all stdout/stderr chatter (requires -o or --output-dir)')
  .option('--rules <paths...>', 'load additional rule files')
  .option('--no-custom-rules', 'skip declarative rules')
  .option('--host <targets...>', 'remote host(s) to scan via SSH (user@host[:port])')
  .option('--inventory <path>', 'YAML file listing hosts to scan')
  .option('--ssh-key <path>', 'SSH identity file for remote connections')
  .option('--ssh-timeout <seconds>', 'SSH connection timeout in seconds', '60')
  .option('--ssh-retries <n>', 'additional SSH attempts after the first failure', '0')
  .option('--parallel <n>', 'max hosts to scan concurrently', '5')
  .option('--sudo', 'attempt privilege escalation via sudo on remote hosts')
  .option('--snapshot <path>', 'scan from a pre-collected probe snapshot file')
  .option('--save-snapshot <dir>', 'after fetching SSH snapshots, write each as <hostname>.json under this directory')
  .option('--no-color', 'disable colored output')
  .option('--fail-on <severity>', 'exit non-zero on findings of this severity or higher (critical, warning, info, none)', 'critical')
  .action(async (options) => {
    if (!validateAgentOption(options) || !validateFormatOption(options)) return;
    const { runScan } = await import('./commands/scan.js');
    await runScan(options);
  });

